import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { SavePoint } from '../types'
import {
  EXCLUDES,
  LOG_FORMAT,
  commitMessage,
  formatWhen,
  gitArgv,
  isUnsafeFolder,
  parseLog,
  promptLabel,
  storeDir,
} from './savepoints'

const PANE = 'salvataggi'
const SHOWN = 30
// The tools that change files: the first of them in a turn takes a save point first.
const CHANGING_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit', 'Bash', 'PowerShell'])

const points = atom({ plugin: 'save-point', key: 'points' } as const, [])
const confirming = atom({ plugin: 'save-point', key: 'confirming' } as const, null)
const isBusy = atom({ plugin: 'save-point', key: 'isBusy' } as const, false)

type Place = { cwd: string; store: string }

async function place($: EngineInterface): Promise<Place | null> {
  const cwd = await $.session.cwd()
  const home = await $.env.get('HOME')
  if (home === undefined || isUnsafeFolder(cwd, home)) {
    return null
  }
  return { cwd, store: storeDir(home, cwd) }
}

async function git($: EngineInterface, where: Place, args: string[], timeoutMs = 120_000) {
  return $.process.run(gitArgv(where.store, where.cwd, args), { cwd: where.cwd, timeoutMs })
}

async function ensureStore($: EngineInterface, where: Place): Promise<void> {
  if (await $.fs.exists(`${where.store}/HEAD`)) {
    return
  }
  await $.process.run(['git', 'init', '--bare', '--quiet', where.store])
  await $.process.run(['git', `--git-dir=${where.store}`, 'config', 'core.bare', 'false'])
  await $.fs.write(`${where.store}/info/exclude`, `${EXCLUDES.join('\n')}\n`)
}

async function refresh($: EngineInterface): Promise<SavePoint[]> {
  const where = await place($)
  if (where === null || !(await $.fs.exists(`${where.store}/HEAD`))) {
    await update($, points, () => [])
    return []
  }
  const log = await git($, where, ['log', `-n${SHOWN}`, `--format=${LOG_FORMAT}`]).catch(() => null)
  const found = log !== null && log.exitCode === 0 ? parseLog(log.stdout) : []
  await update($, points, () => found)
  return found
}

type Saved = 'saved' | 'unchanged' | 'unsafe' | 'failed'

async function save($: EngineInterface, kind: SavePoint['kind'], label: string): Promise<Saved> {
  const where = await place($)
  if (where === null) {
    return 'unsafe'
  }
  try {
    await ensureStore($, where)
    const added = await git($, where, ['add', '--all', '--', ':/'])
    if (added.exitCode !== 0) {
      return 'failed'
    }
    const hasHead = (await git($, where, ['rev-parse', '--verify', '--quiet', 'HEAD'])).exitCode === 0
    const isSame = hasHead && (await git($, where, ['diff', '--cached', '--quiet'])).exitCode === 0
    // An automatic save point of nothing new would only crowd the list; one the person asked for is kept.
    if (isSame && kind !== 'manual') {
      return 'unchanged'
    }
    const committed = await git($, where, ['commit', '--quiet', '--no-verify', '--allow-empty', '-m', commitMessage(kind, label)])
    if (committed.exitCode !== 0) {
      return 'failed'
    }
    await refresh($)
    const now = await $.clock.now()
    $.ui.status(`💾 salvato ${formatWhen(now, now)}`)
    return isSame ? 'unchanged' : 'saved'
  } catch {
    return 'failed'
  }
}

async function restore($: EngineInterface, point: SavePoint): Promise<void> {
  const where = await place($)
  if (where === null) {
    return
  }
  await update($, isBusy, () => true)
  try {
    const now = await $.clock.now()
    const when = formatWhen(point.savedAt, now)
    // What is there now is saved first, so going back can itself be undone.
    await save($, 'restore', `Com'era prima di tornare a ${when}`)
    const restored = await git($, where, ['restore', `--source=${point.sha}`, '--staged', '--worktree', '--', ':/'])
    if (restored.exitCode !== 0) {
      $.ui.toast(`Non sono riuscito a tornare al salvataggio: ${restored.stderr.trim().slice(0, 200)}`)
      return
    }
    await save($, 'restore', `Tornato a ${when}: ${point.label}`)
    await $.session
      .append({
        message: {
          type: 'user',
          content: [
            {
              type: 'text',
              text:
                `[save-point] L'utente ha riportato i file del progetto a com'erano ${when} (${point.label}). ` +
                'Le modifiche fatte dopo non ci sono più: rileggi i file prima di modificarli.',
            },
          ],
        },
      })
      .catch(() => undefined)
    $.ui.toast(`Fatto: i file sono tornati a ${when}. Se cambi idea, il primo salvataggio della lista è com'erano prima.`)
  } finally {
    await update($, confirming, () => null)
    await update($, isBusy, () => false)
  }
}

function describe(result: Saved): string {
  switch (result) {
    case 'saved':
      return 'Salvato. Lo trovi in /salvataggi.'
    case 'unchanged':
      return 'Salvato (nessun file cambiato dall\'ultimo salvataggio).'
    case 'unsafe':
      return 'Non salvo questa cartella: è la tua home o la radice del disco. Apri Claude dentro la cartella del progetto.'
    case 'failed':
      return 'Non sono riuscito a salvare: serve git installato (su Mac: xcode-select --install).'
  }
}

export const register: Register = on => {
  let prompt = ''
  let isSavedThisTurn = false

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'salva',
      description: 'Salva adesso com\'è il progetto (es. /salva funziona il login)',
      argumentHint: '[nome]',
    })
    await $.command.register({
      name: 'salvataggi',
      description: 'I salvataggi del progetto: torna a com\'era prima di una richiesta',
    })
    void refresh($)

    return next(e)
  })

  on('turn.start', ($, e, next) => {
    prompt = e.text
    isSavedThisTurn = false

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    if (!isSavedThisTurn && CHANGING_TOOLS.has(String(e.tool))) {
      isSavedThisTurn = true
      await save($, 'auto', promptLabel(prompt))
    }

    return next(e)
  })

  on('command.run', { command: 'salva' }, async ($, e) => {
    const name = e.args.trim()
    const result = await save($, 'manual', name.length > 0 ? `⭐ ${name}` : '⭐ Salvato a mano')

    return { text: describe(result) }
  })

  on('command.run', { command: 'salvataggi' }, async $ => {
    const found = await refresh($)
    await update($, confirming, () => null)
    await $.ui.open({ id: PANE, title: 'salvataggi', focus: true, closeOnEscape: true })

    return { text: `${found.length} salvataggi per questo progetto.` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const list = await read($, points)
    const pending = await read($, confirming)
    const busy = await read($, isBusy)
    const now = await $.clock.now()

    return (
      <Box flexDirection="column">
        <Text dimColor>
          Prima che Claude modifichi i file salvo com'era il progetto. Scegli un punto per tornarci.
        </Text>
        <Box flexDirection="row" columnGap={1} marginY={1}>
          <Button
            key="save-now"
            label="⭐ Salva adesso"
            variant="primary"
            onPress={async () => {
              $.ui.toast(describe(await save($, 'manual', '⭐ Salvato a mano')))
            }}
          />
        </Box>
        {busy && <Text color="warning">Sto riportando i file indietro…</Text>}
        {list.length === 0 && (
          <Text dimColor>Ancora nessun salvataggio: il primo arriva quando Claude inizia a modificare i file.</Text>
        )}
        {list.map((point, index) => (
          <Box key={`row-${point.sha}`} flexDirection="column">
            <Box flexDirection="row" columnGap={1}>
              <Text dimColor>{formatWhen(point.savedAt, now).padEnd(11)}</Text>
              <Box flexGrow={1}>
                <Text wrap="truncate-end" bold={point.kind === 'manual'} dimColor={point.kind === 'restore'}>
                  {point.label}
                </Text>
              </Box>
              {pending !== point.sha && !busy && (
                <Button
                  key={`back-${index}`}
                  label="Torna qui"
                  onPress={() => update($, confirming, () => point.sha)}
                />
              )}
            </Box>
            {pending === point.sha && !busy && (
              <Box flexDirection="row" columnGap={1} marginLeft={2}>
                <Text color="warning">Riporto tutti i file a {formatWhen(point.savedAt, now)}?</Text>
                <Button key="confirm" label="Sì, torna qui" variant="primary" onPress={() => restore($, point)} />
                <Button key="cancel" label="Annulla" onPress={() => update($, confirming, () => null)} />
              </Box>
            )}
          </Box>
        ))}
      </Box>
    )
  })
}

