import type { SavePoint } from '../types'

// Folders that are rebuilt from scratch or too heavy to copy: never part of a save point.
export const EXCLUDES = [
  'node_modules/',
  '.venv/',
  'venv/',
  '__pycache__/',
  '.next/',
  '.nuxt/',
  '.svelte-kit/',
  '.cache/',
  'dist/',
  'build/',
  'target/',
  '.DS_Store',
  '*.log',
]

const KINDS = ['auto', 'manual', 'restore'] as const

// The save points live outside the project, one git store per folder, so the
// project's own git (if any) never sees them.
export function storeDir(home: string, cwd: string): string {
  const slug = cwd.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
  return `${home}/.claude/save-points/${slug || 'root'}`
}

// Saving the home folder or the disk root would copy everything the person owns.
export function isUnsafeFolder(cwd: string, home: string | undefined): boolean {
  const folder = cwd.replace(/\/+$/, '')
  if (folder === '' || folder === '/') {
    return true
  }
  if (home === undefined) {
    return false
  }
  const homeFolder = home.replace(/\/+$/, '')
  return folder === homeFolder || homeFolder.startsWith(`${folder}/`)
}

export function gitArgv(store: string, cwd: string, args: string[]): string[] {
  return [
    'git',
    `--git-dir=${store}`,
    `--work-tree=${cwd}`,
    '-c', 'user.name=save-point',
    '-c', 'user.email=save-point@localhost',
    '-c', 'commit.gpgsign=false',
    '-c', 'core.hooksPath=/dev/null',
    '-c', 'core.quotepath=false',
    ...args,
  ]
}

export function commitMessage(kind: SavePoint['kind'], label: string): string {
  return `[${kind}] ${label.replace(/\s+/g, ' ').trim()}`
}

export const LOG_FORMAT = '%H%x09%ct%x09%s'

export function parseLog(stdout: string): SavePoint[] {
  return stdout
    .split('\n')
    .filter(line => line.trim().length > 0)
    .flatMap(line => {
      const [sha, seconds, ...rest] = line.split('\t')
      const subject = rest.join('\t')
      const match = /^\[(auto|manual|restore)\] (.*)$/.exec(subject)
      if (sha === undefined || seconds === undefined || match === null) {
        return []
      }
      const kind = KINDS.find(k => k === match[1]) ?? 'auto'
      return [{ sha, savedAt: Number(seconds) * 1000, kind, label: match[2] ?? '' }]
    })
}

// "Prima di: «aggiungi la pagina login»", cut so a long prompt stays one line.
export function promptLabel(prompt: string, max = 60): string {
  const oneLine = prompt.replace(/\[(Image|Pasted text) #\d+[^\]]*\]/g, '').replace(/\s+/g, ' ').trim()
  if (oneLine.length === 0) {
    return 'Prima che Claude modificasse i file'
  }
  const cut = oneLine.length > max ? `${oneLine.slice(0, max - 1).trimEnd()}…` : oneLine
  return `Prima di: «${cut}»`
}

export function formatWhen(savedAt: number, now: number): string {
  const when = new Date(savedAt)
  const time = `${String(when.getHours()).padStart(2, '0')}:${String(when.getMinutes()).padStart(2, '0')}`
  const today = new Date(now)
  const startOfToday = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()
  if (savedAt >= startOfToday) {
    return `oggi ${time}`
  }
  if (savedAt >= startOfToday - 86_400_000) {
    return `ieri ${time}`
  }
  return `${when.getDate()}/${when.getMonth() + 1} ${time}`
}

