export type SavePoint = {
  sha: string
  /** When it was saved, in milliseconds. */
  savedAt: number
  kind: 'auto' | 'manual' | 'restore'
  label: string
}

declare module 'claude-code' {
  interface PluginState {
    'save-point': {
      points: SavePoint[]
      /** The save point waiting for "Sì, torna qui", if any. */
      confirming: string | null
      isBusy: boolean
    }
  }
}
